import {icon,brandMark} from './icons.mjs';
import {GAMES,GAME_BY_ID,MATCHES,FRIENDS,SCREEN_INDEX} from './data.mjs';
import {gameArt,chessBoard,xiangqiBoard,caroBoard,tilesBoard,tileSvg,chessPiece} from './boards.mjs';

export const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function button(label,opts={}){const {href,action,value,variant='primary',ico,cls='',disabled=false}=opts;return `<${href?'a':'button'} ${href?`href="#${href}"`:'type="button"'} class="btn btn-${variant} ${cls}" ${action?`data-action="${action}"`:''} ${value!=null?`data-value="${escapeHtml(value)}"`:''} ${disabled?'disabled aria-disabled="true"':''}>${ico?icon(ico):''}<span>${label}</span></${href?'a':'button'}>`;}
export function avatar(initials='MD',tone='lavender',size=''){return `<span class="avatar ${tone} ${size}">${initials}</span>`;}
export function badge(text,tone='neutral',ico=''){return `<span class="badge badge-${tone}">${ico?icon(ico):''}${text}</span>`;}
export function breadcrumb(text,href='library'){return `<a class="back-link" href="#${href}">${icon('back')}${text}</a>`;}
export function pageHead(eyebrow,title,subtitle='',actions=''){return `<header class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1>${subtitle?`<p class="page-description">${subtitle}</p>`:''}</div>${actions?`<div class="heading-actions">${actions}</div>`:''}</header>`;}
export function emptyState(title,desc,action=''){return `<div class="empty-state">${icon('search')}<h3>${title}</h3><p>${desc}</p>${action}</div>`;}
export function gameCard(g,state){return `<article class="game-card" data-category="${g.category}" data-name="${g.name.toLowerCase()} ${g.label.toLowerCase()}"><a href="#game/${g.id}" class="game-cover ${g.tone}" aria-label="Mở ${g.name}">${gameArt(g.id)}<span class="cover-label">${g.tag}</span></a><div class="game-card-body"><div class="row-between"><a class="game-name" href="#game/${g.id}">${g.name}</a><button class="icon-button favorite ${state.favorites.includes(g.id)?'is-favorite':''}" data-action="favorite" data-value="${g.id}" aria-label="${state.favorites.includes(g.id)?'Bỏ':'Thêm'} ${g.name} ${state.favorites.includes(g.id)?'khỏi':'vào'} yêu thích" aria-pressed="${state.favorites.includes(g.id)}">${icon('heart')}</button></div><div class="game-meta"><span>${icon('users')}${g.players} người</span><span>${icon('clock')}${g.time}</span></div></div></article>`;}
export function libraryScreen(state){
 return `${pageHead('KHÔNG GIAN CHƠI CỦA BẠN','Chơi một ván nhé?','Một khoảng nghỉ nhỏ. Một nước đi mới.',button('Ván của tôi',{href:'history',variant:'tonal',ico:'history'}))}
 <section class="feature-hero"><div class="hero-copy"><span class="eyebrow hero-eyebrow">${icon('spark')} GÓC KHÁM PHÁ MỚI</span><h2>Mỗi nước đi,<br>một điều để học.</h2><p>Cờ tướng cùng gia sư AI.<br>Không chỉ biết đi đâu, mà hiểu vì sao.</p><div class="hero-actions">${button('Khám phá Xiangqi Tutor',{href:'game/xiangqi',ico:'arrow'})}<span class="micro-copy">Chơi · Phân tích · Học</span></div></div><a class="hero-art" href="#game/xiangqi" aria-label="Khám phá Cờ tướng">${gameArt('xiangqi','hero-illustration')}<span class="floating-note">${icon('spark')} Một nước đi. Nhiều góc nhìn.</span></a></section>
 <section class="continue-strip"><span class="continue-icon">${chessPiece('N')}</span><div><span class="eyebrow">BÀN CỜ VẪN ĐỢI BẠN</span><h3>Cờ vua cùng Minh Anh <span class="inline-dot">·</span> <span class="normal muted">Đến lượt bạn</span></h3></div><span class="continue-time">${icon('clock')} 05:42</span>${button('Tiếp tục',{href:'play/chess',variant:'secondary',ico:'arrow'})}</section>
 <section class="catalog-section"><div class="section-heading"><h2>Tìm niềm vui tiếp theo</h2><label class="search-field">${icon('search')}<input id="game-search" type="search" placeholder="Tìm trò chơi…" aria-label="Tìm trò chơi" value="${escapeHtml(state.gameSearch||'')}"><kbd>/</kbd></label></div><div class="filter-row" aria-label="Lọc game">${[['all','Tất cả'],['strategy','Chiến thuật'],['quick','Chơi nhanh'],['party','Hội nhóm'],['favorite','Yêu thích']].map(([id,name])=>`<button class="chip ${state.gameFilter===id?'active':''}" data-action="game-filter" data-value="${id}" aria-pressed="${state.gameFilter===id}">${id==='favorite'?icon('heart'):''}${name}</button>`).join('')}<span class="filter-count">5 trò chơi · bản thiết kế</span></div><div class="game-grid" id="game-grid">${GAMES.map(g=>gameCard(g,state)).join('')}</div><div id="game-empty" hidden>${emptyState('Chưa tìm thấy trò chơi','Thử một từ khóa hoặc bộ lọc khác.')}</div></section>
 <div class="gentle-note">${icon('leaf')} Chơi local không cần tài khoản. Mọi số liệu trong prototype đều là minh họa.</div>`;
}
export function detailScreen(id,state){const g=GAME_BY_ID[id]||GAMES[0];const tutor=g.id==='xiangqi';
 return `${breadcrumb('Thư viện game')}<div class="detail-hero"><div class="detail-art ${g.tone}">${gameArt(g.id,'detail-illustration')}<span class="edition-tag">TABULA ORIGINALS <span>01 / ${g.label.toUpperCase()}</span></span></div><div class="detail-copy"><div class="row gap-8">${badge(tutor?'GAME + GIA SƯ':'BOARD GAME','purple',g.icon)}${badge('Bản thiết kế','neutral')}</div><h1>${g.name}${tutor?'<span>cùng một người thầy.</span>':''}</h1><p>${g.desc}</p><div class="detail-facts"><div>${icon('users')}<strong>${g.players}</strong><span>người chơi</span></div><div>${icon('clock')}<strong>${g.time.replace(' phút','')}</strong><span>phút mỗi ván</span></div><div>${icon('target')}<strong>${g.level}</strong><span>trải nghiệm</span></div></div><div class="detail-cta">${button('Bắt đầu một ván',{href:`setup/${g.id}`,ico:'play'})}${button(state.favorites.includes(g.id)?'Đã yêu thích':'Yêu thích',{action:'favorite',value:g.id,variant:'secondary',ico:'heart'})}</div><div class="micro-note">${icon('info')}${tutor?'Các tính năng engine / gia sư bên dưới là thiết kế đề xuất.':'Bản minh họa giao diện, không phải game hoàn chỉnh.'}</div></div></div>
 <section class="section-spaced"><div class="section-heading"><h2>${tutor?'Bạn muốn bắt đầu thế nào?':'Một trò chơi, nhiều cách kết nối'}</h2><span class="muted">Chọn nhịp chơi của bạn</span></div><div class="mode-cards"><a class="mode-card" href="#setup/${g.id}"><span class="feature-icon lavender">${icon('play')}</span><h3>Chơi một ván</h3><p>${tutor?'Thử sức cùng AI hoặc rủ bạn bè ngồi vào bàn.':'Cùng bạn bè hoặc theo chế độ game hỗ trợ.'}</p><span class="text-link">Bắt đầu ${icon('arrow')}</span></a><a class="mode-card" href="#analysis/${g.id}"><span class="feature-icon sage">${icon('chart')}</span><h3>Xem lại & phân tích</h3><p>Chậm lại một nhịp. Nhìn ván đấu từ một góc khác.</p><span class="text-link">Mở bàn phân tích ${icon('arrow')}</span></a>${tutor?`<a class="mode-card featured-mode" href="#learn/xiangqi"><span class="feature-icon peach">${icon('spark')}</span><h3>Học cùng gia sư</h3><p>Hỏi về một nước đi. Tự tìm lời giải qua từng gợi ý.</p><span class="text-link">Cùng tìm hiểu ${icon('arrow')}</span></a>`:`<a class="mode-card" href="#rooms"><span class="feature-icon peach">${icon('users')}</span><h3>Chơi cùng mọi người</h3><p>Tìm một bàn chơi phù hợp và gặp những người bạn mới.</p><span class="text-link">Xem phòng chơi ${icon('arrow')}</span></a>`}</div></section>
 <section class="detail-bottom"><div class="surface-panel"><div class="section-heading"><h2>Trước nước đi đầu tiên</h2>${icon('book')}</div><p class="muted">Luật chơi ngắn gọn để bạn tự tin bắt đầu. Nội dung đầy đủ sẽ do từng game cung cấp.</p><div class="rule-steps"><span><b>01</b> Chọn chế độ & thời gian</span><span><b>02</b> Làm quen với bàn chơi</span><span><b>03</b> Đến lượt bạn rồi</span></div>${button('Xem luật chơi',{action:'rules',value:g.id,variant:'text',ico:'arrow'})}</div><a class="resource-mini" href="#resources/${g.id}"><span class="feature-icon">${icon('download')}</span><div><h3>Tài nguyên của game</h3><p>Bàn cờ, engine và khả năng chơi offline.</p><span class="text-link">Xem tài nguyên ${icon('arrow')}</span></div></a></section>`;
}
export function setupScreen(id,state){const g=GAME_BY_ID[id]||GAMES[0],s=state.setup;
 return `${breadcrumb(g.name,`game/${g.id}`)}${pageHead('CHUẨN BỊ BÀN CHƠI','Một ván theo cách của bạn.','Chọn đối thủ, nhịp chơi và bắt đầu.')}
 <div class="setup-layout"><form id="setup-form" class="setup-form surface-panel"><section class="form-section"><div class="numbered-title"><span>01</span><div><h2>Bạn sẽ chơi cùng ai?</h2><p>Cấu hình theo khả năng mà game cung cấp.</p></div></div><div class="choice-grid three">${[['local','users','Cùng một máy','Chuyền lượt cho nhau'],['bot','cpu','Huấn luyện viên','Luyện tập với máy'],['online','globe','Bạn bè online','Tạo một phòng riêng']].map(([v,i,n,d])=>{const avail=g.modes.includes(v);return `<label class="choice-card ${s.mode===v?'chosen':''} ${!avail?'unavailable':''}"><input type="radio" name="mode" value="${v}" ${s.mode===v?'checked':''} ${!avail?'disabled':''}>${icon(i)}<strong>${n}</strong><span>${avail?d:'Chưa hỗ trợ trong mẫu'}</span><i class="radio-indicator"></i></label>`}).join('')}</div></section>
 <section class="form-section"><div class="numbered-title"><span>02</span><div><h2>Chọn nhịp chơi</h2><p>Cứ thong thả, hoặc thêm một chút thử thách.</p></div></div><div class="time-options">${[['unlimited','Không giới hạn','Chơi thật thong thả'],['10','10 phút','Một khoảng nghỉ'],['15','15 + 10','Thêm 10 giây mỗi lượt'],['30','30 phút','Dành thời gian suy nghĩ']].map(([v,n,d])=>`<label class="time-choice ${s.time===v?'chosen':''}"><input type="radio" name="time" value="${v}" ${s.time===v?'checked':''}><strong>${n}</strong><span>${d}</span></label>`).join('')}</div></section>
 <section class="form-section"><div class="numbered-title"><span>03</span><div><h2>${s.mode==='bot'?'Mức độ thử thách':'Chỗ ngồi của bạn'}</h2><p>${s.mode==='bot'?'Độ khó là cấu hình minh họa, chưa kết nối engine.':'Chọn bên bạn muốn bắt đầu.'}</p></div></div>${s.mode==='bot'?`<div class="level-choices">${[['easy','Làm quen','Tập trung vào luật và nước đi cơ bản.'],['balanced','Vừa sức','Có thử thách, có khoảng để thử nghiệm.'],['hard','Thử thách','Dành cho những lúc muốn tiến xa hơn.']].map(([v,n,d])=>`<label class="level-choice ${s.level===v?'chosen':''}"><input type="radio" name="level" value="${v}" ${s.level===v?'checked':''}><span class="radio-indicator"></span><span><strong>${n}</strong><small>${d}</small></span></label>`).join('')}</div>`:''}<div class="side-picker"><span>Bên chơi</span><div class="segmented">${[['red',g.id==='chess'?'Trắng':'Đỏ'],['random','Ngẫu nhiên'],['black','Đen']].map(([v,n])=>`<label class="${s.side===v?'active':''}"><input type="radio" name="side" value="${v}" ${s.side===v?'checked':''}>${n}</label>`).join('')}</div></div></section></form>
 <aside class="setup-summary"><div class="summary-art ${g.tone}">${gameArt(g.id)}</div><div class="summary-body"><span class="eyebrow">BÀN CHƠI CỦA BẠN</span><h2>${g.name}</h2><dl class="summary-list"><div><dt>Đối thủ</dt><dd>${s.mode==='bot'?'Huấn luyện viên':s.mode==='online'?'Bạn bè online':'Cùng một máy'}</dd></div><div><dt>Thời gian</dt><dd>${s.time==='unlimited'?'Không giới hạn':s.time==='15'?'15 phút + 10 giây':s.time+' phút'}</dd></div><div><dt>Chế độ</dt><dd>${s.mode==='online'?'Phòng riêng':'Luyện tập · không xếp hạng'}</dd></div></dl><div class="soft-notice">${icon('leaf')}<p>Không áp lực thắng thua.<br>Mỗi ván là một lần khám phá.</p></div>${button(s.mode==='online'?'Tạo phòng chơi':'Vào bàn chơi',{action:'start-match',value:g.id,ico:'arrow',cls:'full-width'})}<p class="center micro-copy">Thiết lập được ghi nhớ trên trình duyệt này.</p></div></aside></div>`;
}
function playerBar(name,sub,time,tone='lavender',active=false,initials='AI'){return `<div class="player-bar ${active?'player-active':''}"><div class="row gap-12">${avatar(initials,tone)}<div><strong>${name}</strong><span>${sub}</span></div></div><div class="player-clock ${active?'clock-active':''}">${active?'<i></i>':''}${time}</div></div>`;}
function modeTabs(id,active){return `<nav class="game-mode-tabs" aria-label="Chế độ game">${[['play','play','Chơi'],['analysis','chart','Phân tích'],['learn','spark','Gia sư']].map(([mode,ico,label])=>`<a href="#${mode}/${id}" class="${active===mode?'active':''}" ${active===mode?'aria-current="page"':''}>${icon(ico)}${label}</a>`).join('')}</nav>`;}
function moveList(id,state){const isChess=id==='chess';const rows=isChess?[['e4','e5'],['Mf3','Mc6'],['Tc4','Mf6'],['d3','Tc5'],['0–0','d6'],['Mc3','0–0']]:[['P2–5','M8.7'],['M2.3','X9–8'],['X1–2','B7.1'],['B7.1','P8.4'],['M8.7','M2.3'],['X9–8','X1–2']];return `<div class="move-table"><div class="move-table-head"><span>Lượt</span><span>${isChess?'Trắng':'Đỏ'}</span><span>Đen</span></div>${rows.map(([a,b],i)=>`<div class="move-row ${i===state.replayStep?'current-move':''}"><span>${i+1}.</span><button data-action="select-move" data-value="${i}" aria-label="Xem lượt ${i+1}, ${a}">${a}</button><button data-action="select-move" data-value="${i}" aria-label="Xem lượt ${i+1}, ${b}">${b}</button></div>`).join('')}${state.demoMoves.map((m,i)=>`<div class="move-row current-move"><span>${rows.length+i+1}.</span><span>${escapeHtml(m)}</span><span>—</span></div>`).join('')}</div>`;}
function replayControls(){return `<div class="replay-controls"><button class="icon-button" data-action="replay-first" aria-label="Về nước đầu">${icon('first')}</button><button class="icon-button" data-action="replay-prev" aria-label="Lùi một nước">${icon('back')}</button><button class="icon-button" data-action="replay-next" aria-label="Tiến một nước">${icon('arrow')}</button><button class="icon-button" data-action="replay-last" aria-label="Đến nước cuối">${icon('last')}</button></div>`;}
function boardTools(id){return `<div class="board-tools"><div class="row gap-4"><button class="icon-button" data-action="flip-board" aria-label="Lật bàn cờ">${icon('refresh')}</button><button class="icon-button" data-action="board-settings" aria-label="Tùy chọn bàn chơi">${icon('settings')}</button><button class="icon-button" data-action="fullscreen" aria-label="Phóng to bàn chơi">${icon('expand')}</button></div><span class="micro-copy">Tương tác mô phỏng · chưa nối luật game</span></div>`;}
function defaultMatchPanel(id,state){return `<aside class="match-side"><section class="surface-panel move-panel"><div class="section-heading"><h2>Nước đi</h2>${badge('Ván mẫu','neutral')}</div>${moveList(id,state)}${replayControls()}</section><section class="turn-card"><span class="status-dot"></span><div><strong>Đến lượt bạn</strong><p>Chọn một quân để xem tương tác minh họa.</p></div></section><section class="quiet-panel"><span class="eyebrow">DÀNH MỘT NHỊP ĐỂ SUY NGHĨ</span><p>Không cần vội.<br>Nhìn cả bàn cờ trước khi chọn một nước đi.</p></section><div class="match-side-actions">${button('Chơi lại',{action:'reset-board',value:id,variant:'secondary',ico:'refresh'})}${button('Kết thúc ván mẫu',{href:`result/${id}`,variant:'text',ico:'flag'})}</div></aside>`;}
export function playScreen(id,state){const g=GAME_BY_ID[id]||GAMES[1];
 if(id==='werewolf')return werewolfScreen(state);
 if(id==='tiles')return tilesScreen(state);
 const board=id==='chess'?chessBoard(state):id==='caro'?caroBoard(state):xiangqiBoard(state);
 return `${breadcrumb('Thư viện game')}${pageHead('BÀN CHƠI · LUYỆN TẬP',g.name,id==='caro'?'Năm quân liên tiếp. Thêm một ván vui.':'Một khoảng thời gian dành cho những nước đi.',badge('Local · bản mẫu','green','shield'))}${id==='xiangqi'?modeTabs(id,'play'):''}
 <div class="match-layout"><section class="board-column">${playerBar(id==='chess'?'Minh Anh':id==='caro'?'Hoàng Nam':'Huấn luyện viên',id==='xiangqi'?'Đối thủ minh họa · không chạy engine':'Cùng một máy · lượt đối phương','08:16','sage',false,id==='chess'?'MA':id==='caro'?'HN':'AI')}<div class="board-stage ${state.boardFlipped?'flipped':''}" id="board-stage">${board}</div>${playerBar('Bạn',id==='chess'?'Quân trắng':id==='caro'?'Quân X':'Quân đỏ','09:42','lavender',true,'MD')}${boardTools(id)}</section>${id==='caro'?`<aside class="match-side"><div class="surface-panel"><span class="eyebrow">VÁN CHƠI CÙNG BẠN</span><h2>Nối liền 5 quân.</h2><p class="muted">Nhấp một ô trống để đặt quân X/O minh họa. Bản mẫu không tự kiểm tra thắng thua.</p><div class="caro-symbols"><span class="symbol-x">×</span><span class="versus">vs</span><span class="symbol-o">○</span></div><div class="soft-notice">${icon('info')}<p>Luật thắng chính xác sẽ do module Caro quyết định.</p></div></div><div class="turn-card"><span class="status-dot"></span><div><strong>Đến lượt ${(state.caro?.length||9)%2?'O':'X'}</strong><p>${state.caro?.length||9} quân đã được đặt</p></div></div><div class="match-side-actions">${button('Chơi lại',{action:'reset-board',value:id,variant:'secondary',ico:'refresh'})}${button('Kết thúc ván mẫu',{href:`result/${id}`,variant:'text',ico:'flag'})}</div></aside>`:defaultMatchPanel(id,state)}</div>`;
}
export function analysisScreen(id,state){if(!['chess','xiangqi'].includes(id))return genericReplayScreen(id,state);const g=GAME_BY_ID[id]||GAMES[0];const isXq=id==='xiangqi';
 return `${breadcrumb('Ván của tôi','history')}${pageHead('KHÔNG GIAN KHÁM PHÁ','Nhìn lại, để đi xa hơn.','Ván luyện tập · Bản replay minh họa',button('Lưu nhánh phân tích',{action:'save-analysis',variant:'tonal',ico:'pin'}))}${isXq?modeTabs(id,'analysis'):''}
 <div class="match-layout analysis-layout"><section class="board-column"><div class="analysis-context"><span>${icon('branch')} Nhánh phân tích riêng</span>${badge(`Nước ${(state.replayStep+1)*2} / 12`,'purple')}</div><div class="board-stage" id="board-stage">${id==='chess'?chessBoard(state):id==='caro'?caroBoard(state):id==='tiles'?tilesBoard(state):xiangqiBoard(state,{arrow:state.analysisArrow})}</div><div class="timeline-control">${replayControls()}<input type="range" min="0" max="5" value="${state.replayStep}" aria-label="Vị trí trong replay" id="replay-slider"><span>${state.replayStep+1} / 6</span></div><div class="soft-notice analysis-safety">${icon('shield')}<p>Bạn đang thử phương án trên bản sao. Ván gốc không thay đổi.</p></div>${boardTools(id)}</section><aside class="match-side"><section class="surface-panel"><div class="section-heading"><h2>Góc nhìn từ engine</h2>${icon('cpu')}</div>${badge('Dữ liệu minh họa · không chạy engine','warning','info')}<div class="evaluation"><strong>+0.42</strong><span>Ví dụ cách hiển thị đánh giá</span><div class="evaluation-bar"><span></span></div></div><div class="analysis-candidates"><button class="candidate ${state.analysisArrow?'chosen':''}" data-action="show-line"><span class="candidate-number">1</span><span><strong>${id==='chess'?'Mf3':'M2.3'} <span>${id==='chess'?'→ Mc6 → Tc4':'→ M8.7 → X1–2'}</span></strong><small>Xem đường đi trên bàn mẫu</small></span><b>+0.42</b></button><button class="candidate" data-action="show-line"><span class="candidate-number">2</span><span><strong>${id==='chess'?'d4':'P2–5'} <span>${id==='chess'?'→ d5 → Mf3':'→ M8.7 → M2.3'}</span></strong><small>Phương án minh họa khác</small></span><b>+0.28</b></button></div><p class="micro-copy">Các nước, điểm số và biểu đồ được dựng để duyệt UI; không dùng làm lời khuyên cờ.</p></section><section class="surface-panel move-panel"><div class="section-heading"><h2>Dòng thời gian</h2><button class="icon-button" data-action="import-position" aria-label="Nhập thế cờ mẫu">${icon('upload')}</button></div>${moveList(id,state)}</section>${isXq?`<a class="tutor-callout" href="#learn/xiangqi"><span class="feature-icon lavender">${icon('spark')}</span><span><strong>Muốn hiểu sâu hơn?</strong><small>Cùng gia sư nhìn lại nước đi.</small></span>${icon('arrow')}</a>`:''}</aside></div>`;
}
export function learnScreen(id,state){
 return `${breadcrumb('Xiangqi Tutor','game/xiangqi')}${pageHead('GIA SƯ CỜ TƯỚNG','Hiểu một nước. Tiến một bước.','Cùng nhìn vào bàn cờ, không chỉ vào câu trả lời.',button('Bài học của bạn',{action:'lessons',variant:'tonal',ico:'book'}))}${modeTabs('xiangqi','learn')}
 <div class="learn-layout"><section class="board-column"><div class="analysis-context"><span>${icon('branch')} Bàn học · tách khỏi ván gốc</span>${badge('Khai cuộc','purple')}</div><div class="board-stage" id="board-stage">${xiangqiBoard(state,{arrow:state.analysisArrow})}</div><div class="learn-board-note"><span class="number-dot">1</span><div><strong>Mục tiêu nhỏ hôm nay</strong><p>Quan sát quân nào chưa tham gia vào thế trận.</p></div></div>${boardTools('xiangqi')}</section><section class="tutor-panel"><div class="tutor-header"><span class="tutor-avatar">${icon('spark')}</span><div><h2>Người bạn bên bàn cờ</h2><span>Gia sư · Hội thoại mẫu</span></div><button class="icon-button" data-action="reset-chat" aria-label="Bắt đầu hội thoại mẫu mới">${icon('edit')}</button></div><div class="ai-disclaimer">${icon('info')} Phản hồi dựng sẵn để duyệt giao diện. Chưa có AI thật.</div><div class="chat-messages" id="chat-messages"><div class="chat-bubble tutor-bubble"><p>Chào bạn. Mình cùng quan sát thế cờ này nhé.</p><p>Trước khi chọn nước đi, bạn thử tìm một quân ở hàng cuối còn chưa có cơ hội tham gia.</p><div class="chat-card"><span class="eyebrow">HỌC QUA CÂU HỎI</span><strong>Bạn muốn khám phá điều gì?</strong><span>Không cần trả lời đúng ngay lần đầu.</span></div></div><div class="chat-bubble user-bubble">Vì sao nên phát triển quân Mã trước?</div><div class="chat-bubble tutor-bubble"><p>Hãy bắt đầu từ hai câu hỏi nhỏ: quân Mã có thêm đường đi nào, và ô nào ở trung tâm được nó hỗ trợ?</p><p>Bấm phương án bên dưới để xem cách một lời giải gắn với bàn cờ.</p><button class="inline-variation" data-action="show-line">${icon('branch')} Xem đường đi minh họa ${icon('arrow')}</button><span class="evidence-label">${icon('info')} Ví dụ trình bày · không phải phân tích engine</span></div>${state.chat.map(m=>`<div class="chat-bubble ${m.role==='user'?'user-bubble':'tutor-bubble'}"><p>${escapeHtml(m.text)}</p></div>`).join('')}</div><div class="tutor-composer"><div class="suggestion-row"><button data-action="chat-prompt" data-value="Cho tôi một gợi ý nhỏ">Một gợi ý nhỏ</button><button data-action="chat-prompt" data-value="Giải thích dễ hiểu hơn">Dễ hiểu hơn</button></div><form id="chat-form"><label class="sr-only" for="chat-input">Câu hỏi cho gia sư mẫu</label><textarea id="chat-input" name="message" rows="2" placeholder="Hỏi về nước đi bạn đang nghĩ tới…" maxlength="500"></textarea><button class="send-button" type="submit" aria-label="Gửi câu hỏi mẫu">${icon('arrow')}</button></form><p class="micro-copy center">Bàn cờ là trung tâm. Lời giải luôn cần có căn cứ.</p></div></section></div>`;
}
export function tilesScreen(state){return `${breadcrumb('Thư viện game')}${pageHead('BÀN CHƠI · 3 NGƯỜI','Miền đất nhỏ','Từng mảnh ghép làm nên một thế giới.',badge('Local · bản mẫu','green','leaf'))}<div class="tiles-players">${[['Bạn','MD','lavender',42],['Bot Rừng','BR','sage',35],['Bot Nắng','BN','peach',28]].map(([n,i,t,s],j)=>`<div class="tile-player ${j===0?'active':''}">${avatar(i,t)}<div><strong>${n}</strong><span>${j===0?'Đến lượt bạn':'Đang chờ'}</span></div><b>${s+(j===0&&state.tilePlaced?4:0)}<small>điểm</small></b></div>`).join('')}</div><div class="match-layout tile-layout"><section class="tiles-stage">${tilesBoard(state)}<div class="map-toolbar"><button class="icon-button" data-action="zoom-out" aria-label="Thu nhỏ bản đồ">${icon('minus')}</button><span>${Math.round((state.tileZoom||1)*100)}%</span><button class="icon-button" data-action="zoom-in" aria-label="Phóng to bản đồ">${icon('plus')}</button><button class="icon-button" data-action="center-map" aria-label="Đưa bản đồ về giữa">${icon('target')}</button></div></section><aside class="match-side"><section class="surface-panel tile-choice-panel"><span class="eyebrow">MẢNH GHÉP CỦA BẠN</span><h2>Một con đường mới</h2><div class="current-tile">${tileSvg(1,state.tileRotation||0)}</div>${button('Xoay mảnh ghép',{action:'rotate-tile',variant:'secondary',ico:'refresh',cls:'full-width'})}<p class="muted center">Nhấp ô nét đứt trên bản đồ để xem thao tác đặt mảnh mẫu.</p>${button(state.tilePlaced?'Đã đặt mảnh':'Đặt vào ô gợi ý',{action:'place-tile',ico:'check',cls:'full-width',disabled:state.tilePlaced})}</section><div class="surface-panel compact"><div class="row-between"><span>Túi mảnh ghép</span><strong>${state.tilePlaced?23:24} / 48</strong></div><div class="progress-line"><span style="width:50%"></span></div><p class="micro-copy">Điểm và vị trí chỉ dùng để mô phỏng giao diện.</p></div>${button('Kết thúc ván mẫu',{href:'result/tiles',variant:'text',ico:'flag'})}</aside></div>`;}
export function werewolfScreen(state){const night=state.wolfNight;const players=['Bạn','Minh Anh','Hoàng Nam','Linh Chi','Tuấn Anh','Phương Thảo','Gia Huy','Ngọc Mai'];return `${breadcrumb('Thư viện game')}${pageHead('BÀN CHƠI · MA SÓI',night?'Khi ngôi làng ngủ.':'Ngôi làng thức giấc.',night?'Đêm thứ 2 · Lắng nghe những điều chưa được nói.':'Ngày thứ 2 · Cùng nhau tìm ra sự thật.',button(night?'Xem pha ban ngày':'Xem pha ban đêm',{action:'wolf-phase',variant:'tonal',ico:night?'sun':'moon'}))}<div class="wolf-layout"><section class="village-panel ${night?'night-phase':''}"><div class="village-status">${badge(night?'PHA ĐÊM':'THẢO LUẬN','neutral',night?'moon':'sun')}<span class="village-clock">01:42 <small>minh họa</small></span></div><div class="village-moon">${icon(night?'moon':'sun')}</div><h2>${night?'Mỗi người, một bí mật.':'Bạn tin tưởng ai?'}</h2><p>${night?'Thông tin vai trò chỉ xuất hiện trong phần riêng của bạn.':'Chọn người chơi để mô phỏng thao tác biểu quyết.'}</p><div class="village-players">${players.map((n,i)=>`<button class="village-player ${state.wolfVote===i?'voted':''}" data-action="wolf-vote" data-value="${i}" ${i===0?'disabled':''}>${avatar(i===0?'MD':n.split(' ').map(s=>s[0]).join(''),['lavender','peach','sage','mint'][i%4],'large')}<strong>${n}</strong><span>${state.wolfVote===i?'Bạn đã chọn':i===0?'Bạn đang chơi':'Còn trong làng'}</span>${state.wolfVote===i?icon('check'):''}</button>`).join('')}</div><div class="village-footer">${icon('shield')} Vai trò những người khác không được hiển thị.</div></section><aside class="match-side"><section class="role-card"><span class="eyebrow">CHỈ MÌNH BẠN THẤY</span><span class="role-illustration">${icon(state.roleRevealed?'eye':'lock')}</span><h2>${state.roleRevealed?'Tiên tri':'Vai trò của bạn'}</h2><p>${state.roleRevealed?'Ví dụ giao diện vai trò riêng. Chưa thực thi luật Ma sói.':'Nhấn để xem vai trò riêng trong bản mẫu.'}</p>${button(state.roleRevealed?'Ẩn vai trò':'Xem vai trò',{action:'reveal-role',variant:'secondary',ico:state.roleRevealed?'lock':'eye',cls:'full-width'})}</section><section class="surface-panel"><div class="section-heading"><h2>Chuyện trong làng</h2>${icon('message')}</div><div class="village-chat"><p><b>Minh Anh</b><span>Mọi người nghĩ sao về lượt vừa rồi?</span></p><p><b>Linh Chi</b><span>Mình muốn nghe Nam giải thích thêm.</span></p></div><div class="soft-notice">${icon('info')}<p>${night?'Chat công khai tạm khóa trong pha đêm mẫu.':'Tin nhắn và người chơi là dữ liệu minh họa.'}</p></div></section></aside></div>`;}
export function resultScreen(id,state){const g=GAME_BY_ID[id]||GAMES[0];return `${breadcrumb('Ván của tôi','history')}<section class="result-hero"><span class="result-spark sp1">✧</span><span class="result-spark sp2">✦</span><span class="result-spark sp3">✧</span><div class="trophy-emblem">${icon('trophy')}</div><span class="eyebrow">MỘT VÁN CHƠI THẬT ĐẸP</span><h1>${id==='tiles'?'Một miền đất, nhiều niềm vui.':'Bạn đã có một ván thắng.'}</h1><p>Điều đáng nhớ không chỉ là kết quả,<br>mà còn là những gì bạn đã nhìn ra.</p><div class="result-match"><div>${avatar('MD','lavender','large')}<strong>Bạn</strong><span>${id==='tiles'?'68 điểm':id==='chess'?'Quân trắng':id==='caro'?'Quân X':'Quân đỏ'}</span></div><strong class="result-score">${id==='tiles'?'1':'1 — 0'}<small>${id==='tiles'?'XẾP HẠNG':'KẾT QUẢ MẪU'}</small></strong><div>${avatar('AI','sage','large')}<strong>Huấn luyện viên</strong><span>${g.name}</span></div></div><div class="result-metrics"><span>${icon('clock')} 18 phút 42 giây</span><span>${icon('layers')} ${id==='tiles'?'24 lượt':'32 nước đi'}</span><span>${icon('shield')} Luyện tập</span></div><div class="result-actions">${button('Cùng nhìn lại ván này',{href:`analysis/${id}`,ico:'chart'})}${button('Chơi thêm một ván',{href:`setup/${id}`,variant:'secondary',ico:'refresh'})}</div><p class="micro-copy">Kết quả được dựng sẵn để duyệt giao diện, không tính từ bàn mẫu.</p></section><div class="result-followups"><a class="mode-card" href="#learn/xiangqi"><span class="feature-icon lavender">${icon('spark')}</span><div><h3>Mỗi ván, một điều mới</h3><p>Hỏi gia sư về một nước đi khiến bạn tò mò.</p></div>${icon('arrow')}</a><a class="mode-card" href="#history"><span class="feature-icon sage">${icon('history')}</span><div><h3>Giữ lại hành trình</h3><p>Xem lại các ván đã lưu của bạn.</p></div>${icon('arrow')}</a></div><div class="center">${button('Về thư viện game',{href:'library',variant:'text',ico:'back'})}</div>`;}
export function historyScreen(state){const filter=state.historyFilter;const list=MATCHES.filter(m=>filter==='all'||m.status===filter);return `${pageHead('HÀNH TRÌNH CỦA BẠN','Mỗi ván, một câu chuyện.','Tiếp tục một ván dở, hoặc nhìn lại một nước đi hay.',button('Nhập replay',{action:'import-replay',variant:'tonal',ico:'upload'}))}<div class="history-highlight"><div class="resume-art">${gameArt('xiangqi')}</div><div><span class="eyebrow">VÁN CHƯA KẾT THÚC</span><h2>Bàn cờ vẫn ở đây.</h2><p>Cờ tướng cùng huấn luyện viên · 12 nước đi</p><span class="text-success">${icon('check')} Đã lưu mẫu trên thiết bị</span></div>${button('Trở lại bàn cờ',{href:'play/xiangqi',ico:'arrow'})}</div><section class="surface-panel history-panel"><div class="section-heading"><div class="filter-row">${[['all','Tất cả'],['playing','Đang chơi'],['done','Đã kết thúc'],['saved','Đã lưu để học']].map(([v,n])=>`<button class="chip ${filter===v?'active':''}" data-action="history-filter" data-value="${v}" aria-pressed="${filter===v}">${n}</button>`).join('')}</div><span class="muted">${list.length} ván mẫu</span></div><div class="history-table"><div class="history-table-head"><span>Ván chơi</span><span>Đối thủ</span><span>Kết quả</span><span>Thời lượng</span><span></span></div>${list.map(m=>`<a class="history-row" href="#${m.status==='playing'?'play':'analysis'}/${m.game}"><div class="history-game"><span class="history-thumb ${GAME_BY_ID[m.game].tone}">${gameArt(m.game)}</span><span><strong>${m.title}</strong><small>${GAME_BY_ID[m.game].name} · ${m.date}</small></span></div><span class="history-opponent">${m.opponent}</span><span>${badge(m.result,m.status==='playing'?'purple':m.status==='saved'?'neutral':'green')}</span><span class="history-duration">${m.time}<small>${m.moves}</small></span>${icon('chevron')}</a>`).join('')}</div>${!list.length?emptyState('Chưa có ván nào ở đây','Các ván bạn lưu sẽ xuất hiện tại đây.'):''}</section><div class="gentle-note">${icon('folder')} Dữ liệu minh họa. Không có đồng bộ tài khoản hay replay thật trong prototype.</div>`;}
function toggleRow(label,desc,key,state,ico){return `<div class="setting-row"><div class="row gap-16">${ico?`<span class="setting-icon">${icon(ico)}</span>`:''}<div><strong>${label}</strong><p>${desc}</p></div></div><button role="switch" aria-checked="${!!state.prefs[key]}" aria-label="${label}" class="switch ${state.prefs[key]?'on':''}" data-action="toggle-setting" data-value="${key}"><span>${state.prefs[key]?icon('check'):''}</span></button></div>`;}
export function settingsScreen(state){return `${pageHead('THEO CÁCH CỦA BẠN','Một không gian dễ chịu.','Những điều nhỏ làm nên trải nghiệm chơi của riêng bạn.')}<div class="settings-layout"><nav class="settings-nav" aria-label="Nhóm cài đặt"><a href="#settings" class="active">${icon('sun')} Giao diện</a><a href="#settings" data-action="scroll-section" data-value="sound-settings">${icon('volume')} Âm thanh & chuyển động</a><a href="#settings" data-action="scroll-section" data-value="data-settings">${icon('folder')} Dữ liệu & riêng tư</a><a href="#resources/xiangqi">${icon('cpu')} Tài nguyên game</a><a href="#login">${icon('user')} Tài khoản</a></nav><div class="settings-content"><section class="surface-panel"><div class="section-heading"><h2>Ánh sáng phù hợp với bạn</h2>${icon('sun')}</div><p class="muted">Bộ màu theo semantic token của Tabula. Không cần tải thêm.</p><div class="theme-options">${[['light','Sáng','sun'],['dark','Tối','moon'],['system','Theo thiết bị','cpu']].map(([v,n,i])=>`<button class="theme-option ${state.prefs.theme===v?'selected':''}" data-action="theme" data-value="${v}" aria-pressed="${state.prefs.theme===v}"><div class="theme-preview theme-${v}"><i></i><div><span></span><b></b><b></b></div></div><span>${icon(i)}${n}${state.prefs.theme===v?icon('check'):''}</span></button>`).join('')}</div>${toggleRow('Tương phản cao','Tăng độ rõ của chữ và đường phân cách.','contrast',state,'eye')}<div class="setting-row"><div class="row gap-16"><span class="setting-icon">${icon('globe')}</span><div><strong>Ngôn ngữ</strong><p>Prototype hiện có nội dung tiếng Việt.</p></div></div><span class="badge">Tiếng Việt</span></div></section><section class="surface-panel" id="sound-settings"><h2>Âm thanh & chuyển động</h2>${toggleRow('Âm thanh bàn chơi','Công tắc mẫu; prototype không phát âm thanh.','sound',state,'volume')}${toggleRow('Giảm chuyển động','Loại bỏ chuyển cảnh và các chuyển động phụ.','reducedMotion',state,'leaf')}</section><section class="surface-panel" id="data-settings"><h2>Dữ liệu & riêng tư</h2><div class="setting-row"><div class="row gap-16"><span class="setting-icon">${icon('shield')}</span><div><strong>Chỉ trên trình duyệt này</strong><p>Prototype không gửi dữ liệu đến máy chủ.</p></div></div>${badge('Local','green')}</div><div class="setting-row"><div><strong>Đặt lại bản mẫu</strong><p>Xóa cài đặt, yêu thích và tương tác mẫu đã lưu.</p></div>${button('Đặt lại',{action:'reset-demo',variant:'danger'})}</div><a href="#design-system" class="setting-row link-row"><span><strong>Bộ thành phần & token</strong><p>Xem bảng màu, trạng thái và cấu trúc giao diện.</p></span>${icon('arrow')}</a></section></div></div>`;}
export function resourcesScreen(id,state){const g=GAME_BY_ID[id]||GAMES[0];return `${breadcrumb(g.name,`game/${g.id}`)}${pageHead('TÀI NGUYÊN CỦA GAME','Sẵn sàng, theo nhu cầu.','Bật thêm khả năng khi bạn cần. Không tự tải hay chuyển sang cloud.',badge('Quản lý local','green','shield'))}<section class="resource-banner"><span class="feature-icon sage">${icon('leaf')}</span><div><h2>Chơi trước. Mở rộng sau.</h2><p>Luật và bàn chơi độc lập với engine, gia sư hoặc dịch vụ bên ngoài.</p></div><span class="resource-banner-art">${icon('layers')}</span></section><div class="resource-cards"><section class="resource-card"><div class="row-between"><span class="feature-icon lavender">${icon('grid')}</span>${badge('Có trong bản mẫu','green','check')}</div><h2>Bàn chơi & hình ảnh</h2><p>Bàn cờ, quân cờ và giao diện SVG. Được đóng gói cùng prototype.</p><dl><div><dt>Nguồn</dt><dd>Asset minh họa tự tạo</dd></div><div><dt>Kết nối</dt><dd>Không cần mạng</dd></div></dl>${button('Mở bàn chơi',{href:`play/${g.id}`,variant:'secondary',ico:'play',cls:'full-width'})}</section><section class="resource-card"><div class="row-between"><span class="feature-icon sage">${icon('cpu')}</span>${badge(state.engineInstalled?'Đã cài (mô phỏng)':'Chưa cài','neutral')}</div><h2>Engine phân tích</h2><p>Đề xuất nước đi và đánh giá thế cờ. Provider, artifact và điều kiện phân phối cần chốt khi triển khai.</p><dl><div><dt>Vai trò</dt><dd>Chơi & phân tích</dd></div><div><dt>Trạng thái</dt><dd>UI minh họa</dd></div></dl>${button(state.engineInstalled?'Gỡ trạng thái mẫu':'Mô phỏng cài đặt',{action:'install-engine',variant:state.engineInstalled?'secondary':'primary',ico:'download',cls:'full-width'})}</section><section class="resource-card"><div class="row-between"><span class="feature-icon peach">${icon('spark')}</span>${badge('Tùy chọn','purple')}</div><h2>Giải thích bằng lời</h2><p>Diễn giải dựa trên dữ liệu phân tích. Không thay luật game, không tự quyết định nước đi.</p><dl><div><dt>Nội dung demo</dt><dd>Phản hồi dựng sẵn</dd></div><div><dt>Model / API</dt><dd>Chưa kết nối</dd></div></dl>${button('Xem gia sư mẫu',{href:'learn/xiangqi',variant:'secondary',ico:'arrow',cls:'full-width'})}</section></div><section class="surface-panel resource-budget"><div><span class="eyebrow">BẠN GIỮ QUYỀN KIỂM SOÁT</span><h2>Để máy vẫn thật nhẹ.</h2><p class="muted">Thiết kế giới hạn tài nguyên dành cho engine sau này. Các thanh chọn dưới đây không điều khiển tiến trình thật.</p></div><div><label class="range-field"><span>Ngân sách CPU <b id="cpu-value">${state.cpuBudget||25}%</b></span><input id="cpu-budget" type="range" min="10" max="80" step="5" value="${state.cpuBudget||25}"></label><div class="setting-row"><span>Chỉ tải khi bạn xác nhận</span>${badge('Luôn bật','green','check')}</div></div></section><div class="gentle-note">${icon('info')} Không bundle engine, model, weights hay font trong bộ thiết kế này.</div>`;}
export function authScreen(register,state){return `<div class="auth-layout"><section class="auth-story"><a class="auth-brand" href="#library">${brandMark()}<span>tabula</span></a><div><span class="eyebrow">MỘT BÀN CHƠI. NHIỀU KẾT NỐI.</span><h1>Niềm vui lớn,<br>từ một ván nhỏ.</h1><p>Chơi cùng bạn bè, lưu lại hành trình<br>và khám phá điều mới mỗi ngày.</p></div><div class="auth-art">${gameArt('chess','detail-illustration')}</div><span class="auth-story-footer">Cứ ngồi xuống. Luôn có một chỗ dành cho bạn.</span></section><section class="auth-form-side">${breadcrumb('Trở lại thư viện')}<div class="auth-form-wrap"><span class="eyebrow">${register?'RẤT VUI ĐƯỢC GẶP BẠN':'CHÀO BẠN TRỞ LẠI'}</span><h2>${register?'Cùng bắt đầu nhé.':'Bàn chơi đang đợi.'}</h2><p>${register?'Tạo hồ sơ để kết nối với những người bạn mới.':'Đăng nhập để tiếp tục hành trình của bạn.'}</p><form id="auth-form" data-register="${register}">${register?'<label class="input-label">Tên hiển thị<input type="text" name="displayName" placeholder="Bạn muốn mọi người gọi là gì?" autocomplete="nickname" required maxlength="40"></label>':''}<label class="input-label">Email<input type="email" name="email" placeholder="ban@example.com" autocomplete="email" required></label><label class="input-label">Mật khẩu mẫu<span class="password-field"><input id="password" type="password" name="password" placeholder="Chỉ dùng mật khẩu thử, không dùng mật khẩu thật" minlength="6" required autocomplete="off"><button type="button" class="icon-button" data-action="show-password" aria-label="Hiện hoặc ẩn mật khẩu">${icon('eye')}</button></span></label>${register?'<label class="check-label"><input type="checkbox" required> Tôi hiểu đây là form minh họa, không tạo tài khoản thật.</label>':`<div class="auth-options"><label class="check-label"><input type="checkbox"> Ghi nhớ phiên mẫu</label><button type="button" class="text-button" data-action="forgot-password">Quên mật khẩu?</button></div>`}<button class="btn btn-primary full-width" type="submit">${register?'Tạo hồ sơ mẫu':'Đăng nhập mẫu'}${icon('arrow')}</button></form><div class="auth-separator"><span>hoặc cứ bắt đầu chơi</span></div>${button('Tiếp tục không cần tài khoản',{href:'library',variant:'secondary',ico:'play',cls:'full-width'})}<p class="auth-switch">${register?'Đã có tài khoản?':'Lần đầu ghé Tabula?'} <a href="#${register?'login':'register'}">${register?'Đăng nhập':'Tạo tài khoản'}</a></p><div class="soft-notice">${icon('shield')}<p>Không gửi hay lưu mật khẩu. Mọi thao tác chỉ mô phỏng trên trình duyệt.</p></div></div></section></div>`;}
const ROOMS=[['Bàn cờ buổi sáng','chess','Minh Anh','1 / 2','10 phút','Nhẹ nhàng'],['Cùng học một nước hay','xiangqi','Linh Chi','1 / 2','15 + 10','Luyện tập'],['Xây một miền đất mới','tiles','Tuấn Anh','2 / 4','Không giới hạn','Chào đón bạn'],['Caro thêm một ván','caro','Hoàng Nam','1 / 2','5 phút','Chơi nhanh'],['Ngôi làng cuối tuần','werewolf','Phương Thảo','6 / 8','30 phút','Bản thiết kế'],['Một bàn cờ thong thả','chess','Gia Huy','1 / 2','30 phút','Không xếp hạng']];
export function roomsScreen(state){return `${pageHead('CÙNG CHƠI VUI HƠN','Luôn có một bàn trống.','Tìm một nhịp chơi hợp nhau. Phần online hiện là dữ liệu mô phỏng.',button('Tạo phòng',{action:'create-room',ico:'plus'}))}<div class="room-discovery"><div><span class="eyebrow">KHÔNG BIẾT BẮT ĐẦU TỪ ĐÂU?</span><h2>Để một ván chơi kết nối chúng mình.</h2><p>Chọn ghép trận để xem luồng tìm đối thủ mẫu.</p></div>${button('Tìm đối thủ',{href:'queue',variant:'secondary',ico:'bolt'})}<span class="discovery-art">${icon('users')}</span></div><div class="room-searchbar"><label class="search-field">${icon('search')}<input id="room-search" type="search" placeholder="Tìm phòng, game hoặc người chơi…" aria-label="Tìm phòng"></label><div class="filter-row">${[['all','Tất cả game'],['chess','Cờ vua'],['xiangqi','Cờ tướng'],['other','Game khác']].map(([v,n])=>`<button class="chip ${state.roomFilter===v?'active':''}" data-action="room-filter" data-value="${v}">${n}</button>`).join('')}</div>${button('Nhập mã',{action:'join-code',variant:'text',ico:'link'})}</div><div class="room-grid" id="room-grid">${ROOMS.filter(r=>state.roomFilter==='all'||r[1]===state.roomFilter||state.roomFilter==='other'&&!['chess','xiangqi'].includes(r[1])).map(([title,game,host,seats,time,tag],i)=>`<article class="room-card" data-name="${escapeHtml((title+' '+GAME_BY_ID[game].name+' '+host).toLowerCase())}"><div class="row-between"><span class="room-game-icon ${GAME_BY_ID[game].tone}">${icon(GAME_BY_ID[game].icon)}</span>${badge(tag,'neutral')}</div><span class="room-game-label">${GAME_BY_ID[game].name}</span><h3>${title}</h3><div class="room-host">${avatar(host.split(' ').map(s=>s[0]).join(''),GAME_BY_ID[game].tone,'small')}<span>${host}</span><span class="status-dot"></span></div><div class="room-card-footer"><span>${icon('users')} ${seats}</span><span>${icon('clock')} ${time}</span>${button('Vào phòng',{action:'join-room',value:game,variant:'tonal',ico:'arrow'})}</div></article>`).join('')}</div><div class="gentle-note">${icon('info')} Chưa có server, tài khoản hay người chơi trực tuyến thật.</div>`;}
export function roomScreen(state){const g=GAME_BY_ID[state.roomGame]||GAMES[1];return `${breadcrumb('Phòng chơi','rooms')}${pageHead('PHÒNG RIÊNG · MÃ TB-2086','Một chỗ dành cho bạn.','Chào nhau một câu, sẵn sàng và bắt đầu một ván.',button('Mời bạn',{action:'copy-room',variant:'tonal',ico:'link'}))}<div class="room-layout"><section class="surface-panel waiting-room"><div class="row-between"><div class="row gap-12"><span class="room-game-icon ${g.tone}">${icon(g.icon)}</span><div><h2>${escapeHtml(state.roomName||g.name+' cùng bạn bè')}</h2><span class="muted">10 phút · Không xếp hạng</span></div></div>${badge('Phòng mẫu','purple')}</div><div class="seats-grid"><div class="seat-card">${badge('Chủ phòng','neutral')}${avatar('MA','peach','xl')}<h3>Minh Anh</h3><p>Người chơi mẫu</p><span class="ready-status">${icon('check')} Đã sẵn sàng</span></div><div class="seat-card your-seat ${state.ready?'seat-ready':''}">${badge('Bạn','purple')}${avatar('MD','lavender','xl')}<h3>${escapeHtml(state.displayName||'Mạnh Duy')}</h3><p>Ghế số 2</p><span class="${state.ready?'ready-status':'muted'}">${icon(state.ready?'check':'clock')}${state.ready?'Đã sẵn sàng':'Chờ bạn sẵn sàng'}</span></div></div><div class="room-ready-footer"><span>${icon('shield')} Không dùng trợ giúp trong trận nếu luật không cho phép.</span>${button(state.ready?'Hủy sẵn sàng':'Tôi đã sẵn sàng',{action:'toggle-ready',variant:state.ready?'secondary':'primary',ico:state.ready?'close':'check'})}</div><div class="room-start">${button('Bắt đầu ván mẫu',{action:'start-room',ico:'play',disabled:!state.ready,cls:'full-width'})}<p class="micro-copy center">Không kết nối người chơi thật; nút này mở bàn local minh họa.</p></div></section><aside class="room-side"><section class="surface-panel"><div class="section-heading"><h2>Cấu hình phòng</h2>${icon('settings')}</div><dl class="summary-list"><div><dt>Chế độ</dt><dd>Luyện tập</dd></div><div><dt>Quyền truy cập</dt><dd>Chỉ người có mã</dd></div><div><dt>Người xem</dt><dd>Tắt</dd></div></dl>${button('Đổi thiết lập',{href:`setup/${g.id}`,variant:'text',ico:'edit'})}</section><section class="surface-panel room-chat"><h2>Lời chào trước ván</h2><div class="room-chat-content"><span class="chat-timestamp">Hôm nay · dữ liệu mẫu</span><div class="room-chat-line">${avatar('MA','peach','small')}<p><b>Minh Anh</b>Chơi thong thả thôi nhé 😊</p></div>${state.roomChat.map(t=>`<div class="room-chat-line">${avatar('MD','lavender','small')}<p><b>Bạn</b>${escapeHtml(t)}</p></div>`).join('')}</div><form id="room-chat-form"><input name="message" maxlength="200" placeholder="Gửi lời chào mẫu…" aria-label="Tin nhắn phòng mẫu" required><button type="submit" class="icon-button" aria-label="Gửi tin nhắn mẫu">${icon('send')}</button></form></section></aside></div>`;}
export function queueScreen(state){return `${breadcrumb('Phòng chơi','rooms')}<section class="queue-screen"><div class="queue-visual"><span class="orbit o1"></span><span class="orbit o2"></span><span class="queue-avatar qa1">${avatar('MD','lavender','xl')}</span><span class="queue-avatar qa2">${icon('users')}</span><span class="queue-spark">✦</span></div>${badge('LUỒNG GHÉP TRẬN MẪU','purple')}<h1>Người bạn cùng bàn<br>đang ở đâu đó.</h1><p>Đang tìm một đối thủ cùng nhịp chơi.<br>Prototype không gọi dịch vụ ghép trận thật.</p><div class="queue-timer">00:18 <small>thời gian minh họa</small></div><div class="queue-prefs"><span>${icon('trophy')} Cờ vua</span><span>${icon('clock')} 10 phút</span><span>${icon('shield')} Không xếp hạng</span></div><div class="queue-actions">${button('Xem kết quả ghép mẫu',{action:'mock-match-found',ico:'users'})}${button('Hủy tìm kiếm',{href:'rooms',variant:'secondary',ico:'close'})}</div><div class="queue-tip"><span class="feature-icon sage">${icon('leaf')}</span><div><strong>Trong lúc này, thả lỏng một chút.</strong><p>Rời mắt khỏi màn hình, hít thở và chuẩn bị cho một ván vui.</p></div></div></section>`;}
export function profileScreen(state){return `${pageHead('GÓC CỦA BẠN','Một hành trình riêng.','Hồ sơ và thống kê minh họa, chưa liên kết tài khoản thật.',button('Chỉnh sửa hồ sơ',{action:'edit-profile',variant:'tonal',ico:'edit'}))}<section class="profile-hero"><div class="profile-stripe"></div>${avatar('MD','lavender','profile-avatar')}<div class="profile-info"><span class="eyebrow">NGƯỜI BẠN CỦA TABULA</span><h1>${escapeHtml(state.displayName||'Mạnh Duy')}</h1><p>@manhduy · Thích những ván cờ thong thả</p><div class="profile-badges">${badge('Người khám phá','purple','spark')}${badge('Thành viên mẫu','neutral','leaf')}</div></div><div class="profile-quote">“Chơi để vui.<br>Hiểu để tiến bộ.”</div></section><div class="profile-stats">${[['24','Ván đã chơi','layers'],['14','Ván thắng','trophy'],['5','Trò chơi khám phá','grid'],['3','Ván lưu để học','book']].map(([n,l,i])=>`<div class="stat-card">${icon(i)}<strong>${n}</strong><span>${l}</span></div>`).join('')}</div><div class="profile-bottom"><section class="surface-panel"><div class="section-heading"><h2>Những bàn chơi yêu thích</h2><a class="text-link" href="#library">Thư viện ${icon('arrow')}</a></div>${GAMES.slice(0,3).map((g,i)=>`<a class="favorite-game-row" href="#game/${g.id}"><span class="history-thumb ${g.tone}">${gameArt(g.id)}</span><span><strong>${g.name}</strong><small>${[12,8,4][i]} ván mẫu</small></span><div class="mini-bar"><i style="width:${[90,65,35][i]}%"></i></div>${icon('chevron')}</a>`).join('')}</section><section class="surface-panel"><div class="section-heading"><h2>Một bước nhỏ mỗi ngày</h2>${icon('spark')}</div><div class="achievement-art">${icon('book')}</div><h3>Luôn giữ sự tò mò</h3><p class="muted">Bạn không cần thắng mọi ván để tìm thấy một điều mới.</p>${button('Ghé góc học cờ',{href:'learn/xiangqi',variant:'tonal',ico:'arrow'})}</section></div>`;}
export function friendsScreen(state){return `${pageHead('NHỮNG NGƯỜI BẠN CÙNG BÀN','Có bạn, vui hơn.','Một lời mời nhỏ có thể mở đầu một ván chơi hay.',button('Thêm bạn',{action:'add-friend',ico:'plus'}))}<section class="friend-invite"><span class="feature-icon peach">${icon('mail')}</span><div><h3>${state.friendAccepted?'Đã thêm Ngọc Mai vào danh sách mẫu':'Ngọc Mai muốn kết nối với bạn'}</h3><p>${state.friendAccepted?'Đây chỉ là thay đổi trong prototype.':'Lời mời minh họa · 2 game yêu thích chung'}</p></div>${button(state.friendAccepted?'Đã chấp nhận':'Chấp nhận',{action:'accept-friend',variant:'tonal',ico:'check',disabled:state.friendAccepted})}</section><section class="surface-panel friends-panel"><div class="section-heading"><div class="filter-row">${[['all','Tất cả bạn bè'],['online','Đang hoạt động']].map(([v,n])=>`<button class="chip ${state.friendFilter===v?'active':''}" data-action="friend-filter" data-value="${v}">${n}</button>`).join('')}</div><label class="search-field">${icon('search')}<input type="search" id="friend-search" placeholder="Tìm bạn…" aria-label="Tìm bạn"></label></div><div id="friends-list">${FRIENDS.filter(f=>state.friendFilter==='all'||f.online).map(f=>`<div class="friend-row" data-name="${f.name.toLowerCase()}"><span class="avatar-status">${avatar(f.initials,f.tone,'large')}${f.online?'<i></i>':''}</span><div><h3>${f.name}</h3><p>${f.status}${f.game?' · '+f.game:''}</p></div><span class="friend-handle">@${f.handle}</span>${button('Mời chơi',{action:'invite-friend',value:f.name,variant:'secondary',ico:'play'})}</div>`).join('')}</div></section><div class="gentle-note">${icon('info')} Danh sách, trạng thái và lời mời đều là ví dụ. Không gửi thông báo thật.</div>`;}
export function designSystemScreen(state){return `${pageHead('TABULA · DESIGN FOUNDATION','Chung một ngôn ngữ.','M3 Expressive-inspired · semantic token từ repository, bổ sung lớp prototype.',button('Danh sách màn hình',{action:'screen-index',variant:'tonal',ico:'grid'}))}<div class="design-intro"><span class="eyebrow">CHỦ ĐÍCH THIẾT KẾ</span><h2>Ấm áp như một bàn chơi.<br>Rõ ràng như một nước đi.</h2><p>Nền giấy sáng, nhịp thở rộng, màu tím có tiết chế. Các game có cá tính riêng, nhưng điều hướng và hành vi luôn quen thuộc.</p></div><section class="surface-panel"><div class="section-heading"><h2>Màu sắc có vai trò</h2><span class="muted">tokens.toml → CSS variables</span></div><div class="swatches">${[['primary','Chủ đạo','#5634BE'],['surface','Bề mặt','#FFFBFF'],['container','Lớp nền','#F4EDF7'],['on-surface','Nội dung','#1E1C21'],['success','Sẵn sàng','#106F3D'],['danger','Lỗi','#BA1A1A']].map(([v,n,h])=>`<div><span class="swatch" style="background:var(--${v})"></span><strong>${n}</strong><code>${h}</code></div>`).join('')}</div></section><div class="design-columns"><section class="surface-panel"><h2>Kiểu chữ</h2><div class="type-display">Mỗi nước đi,<br>một câu chuyện.</div><p>Serif cho những khoảnh khắc cảm xúc. Sans-serif cho thông tin và thao tác.</p><code>Georgia / ui-serif · system-ui / ui-sans-serif</code><p class="micro-copy">Không đóng gói font. Hiển thị có thể khác nhẹ giữa thiết bị.</p></section><section class="surface-panel"><h2>Thành phần tương tác</h2><div class="component-samples">${button('Bắt đầu một ván',{action:'sample-toast',ico:'play'})}${button('Khám phá',{action:'sample-toast',variant:'tonal',ico:'arrow'})}${button('Tùy chọn',{action:'sample-toast',variant:'secondary',ico:'settings'})}${button('Chưa sẵn sàng',{disabled:true})}</div><div class="component-samples">${badge('Đã lưu','green','check')}${badge('Luyện tập','purple')}${badge('Thiếu tài nguyên','warning','info')}</div>${toggleRow('Công tắc minh họa','Trạng thái ghi nhớ trên trình duyệt.','sound',state)}</section></div><section class="surface-panel section-spaced"><h2>Trạng thái cũng cần được thiết kế</h2><div class="component-samples">${button('Đang tải tài nguyên',{action:'loading-demo',variant:'secondary',ico:'download'})}${button('Mất kết nối',{action:'connection-demo',variant:'secondary',ico:'wifi'})}${button('Trạng thái trống',{action:'empty-demo',variant:'secondary',ico:'folder'})}${button('Xác nhận thao tác',{action:'reset-demo',variant:'secondary',ico:'shield'})}</div><p class="muted">Nút rõ nghĩa, focus nhìn thấy, modal hỗ trợ Escape, chuyển động theo tùy chọn thiết bị, bố cục đáp ứng trên mobile.</p></section>`;}
export function screenContent(route,state){const [screen,id]=route.split('/');switch(screen){case'library':return libraryScreen(state);case'game':return detailScreen(id,state);case'setup':return setupScreen(id,state);case'play':return playScreen(id,state);case'result':return resultScreen(id,state);case'history':return historyScreen(state);case'analysis':return analysisScreen(id,state);case'learn':return learnScreen(id,state);case'settings':return settingsScreen(state);case'resources':return resourcesScreen(id,state);case'login':return authScreen(false,state);case'register':return authScreen(true,state);case'rooms':return roomsScreen(state);case'room':return roomScreen(state);case'queue':return queueScreen(state);case'profile':return profileScreen(state);case'friends':return friendsScreen(state);case'design-system':return designSystemScreen(state);default:return `${pageHead('TRANG CHƯA CÓ','Lạc một nước, không sao.','Quay lại thư viện để bắt đầu một ván mới.')}${button('Về thư viện',{href:'library',ico:'back'})}`;}}

export function genericReplayScreen(id,state){const g=GAME_BY_ID[id]||GAMES[2];const board=id==='tiles'?tilesBoard(state):id==='caro'?caroBoard(state):'<div class="surface-panel">'+emptyState('Replay có thông tin riêng','Khi triển khai Ma sói, replay phải tuân thủ quyền xem và quy tắc lộ vai trò.')+'</div>';return `${breadcrumb('Ván của tôi','history')}${pageHead('REPLAY · '+g.name.toUpperCase(),'Chậm lại một lượt.','Dòng sự kiện minh họa, không phải bản tái tạo ván thật.')}<div class="match-layout"><section class="board-column"><div class="analysis-context"><span>${icon('history')} Xem lại ván mẫu</span>${badge('Lượt '+(state.replayStep+1),'purple')}</div>${board}<div class="timeline-control">${replayControls()}<input type="range" min="0" max="5" value="${state.replayStep}" id="replay-slider" aria-label="Vị trí replay"><span>${state.replayStep+1} / 6</span></div></section><aside class="match-side"><section class="surface-panel"><h2>Dòng sự kiện</h2>${['Bắt đầu ván','Người chơi thứ nhất thực hiện lượt','Chuyển lượt','Người chơi thứ hai thực hiện lượt','Cập nhật bàn chơi','Chờ lượt tiếp theo'].map((text,i)=>`<button class="candidate ${i===state.replayStep?'chosen':''}" data-action="select-move" data-value="${i}"><span class="candidate-number">${i+1}</span><span><strong>${text}</strong><small>Sự kiện giao diện minh họa</small></span></button>`).join('')}</section><div class="soft-notice">${icon('shield')}<p>Chỉ hiển thị capability game hỗ trợ. Không gắn engine cờ tướng vào replay của game khác.</p></div>${button('Chơi một ván mới',{href:'setup/'+g.id,ico:'play'})}</aside></div>`;}
